INSERT INTO accompany.dbo.user_reminders (content,created_at,updated_at) VALUES
	 (N'<p>&lt;h3 class="default-title"&gt;給服務使用者的小叮嚀&lt;/h3&gt;&lt;p class="reminder-intro mb-4"&gt;面對「陪伴照顧服務工作者」，提醒您注意以下事項，相信有助於溝通與照顧品質：&lt;/p&gt;&lt;ul class="reminder-list"&gt;&lt;li&gt;&lt;strong&gt;交接被照顧者的重要資訊或注意事項&lt;/strong&gt;，例如用藥、飲食習慣、喜好等。 &lt;/li&gt;&lt;li&gt;&lt;strong&gt;依據被照顧者生活作息，事前共同訂定&lt;/strong&gt;用餐、如廁、復健、休息等照顧時間表。 &lt;/li&gt;&lt;li&gt;&lt;strong&gt;尊重不同飲食文化與信仰&lt;/strong&gt;。例如穆斯林因信仰關係不食用豬肉。&lt;/li&gt;&lt;li&gt;&lt;strong&gt;提供必要休息時間與能安心休息的空間&lt;/strong&gt;。 &lt;/li&gt;&lt;/ul&gt;&lt;p class="reminder-note mt-4"&gt;&lt;span class="text-black"&gt;★&lt;/span&gt; 若有任何問題，可致電各試辦單位，他們將會即時提供協助。&lt;/p&gt;</p>','2025-04-13 07:33:47.1366667','2025-04-13 09:14:50.5500000');
